# Exact GET-only guard diagnostic. No guard is bypassed and no resource effect is added.
$ErrorActionPreference='Stop'
$script:OffconfigDiagnosticGuard=$null
try {
 & ([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))))
} catch {
 $label=$script:OffconfigDiagnosticGuard
 if($null -eq $label -or $label.Length -gt 512 -or $label -cnotmatch '^(OFFCONFIG: |Installed MOC module/signature/required-parameter contract differs)' -or $label -match '(?i:password|access_token|refresh_token|client_secret|authorization|-----BEGIN|[\r\n])'){$label='static-guard-label-unavailable'}
 $lines=@([regex]::Matches([string]$_.ScriptStackTrace,'line (\d+)')|ForEach-Object {[int]$_.Groups[1].Value}|Select-Object -First 12)
 @{status='original-offconfig-GET-guard-refused';inputSourceSha256='30e528cd0a530d3852f8263868bcf37e01a5138ac0da6420925b443d917a7ad1';guardLabel=$label;exceptionType=$_.Exception.GetType().FullName;assertionLine=$_.InvocationInfo.ScriptLineNumber;stackLines=$lines;resourceMutationPerformed=$false;actualGoIssued=$false;atUtc=[datetime]::UtcNow.ToString('o')}|ConvertTo-Json -Depth 8 -Compress
}
